import functools


def retry(times):
    def wrap(test):
        @functools.wraps(test)
        def run(*args, **kwargs):
            for attempt in range(times):
                try:
                    return test(*args, **kwargs)
                except AssertionError:
                    if attempt == times - 1:
                        raise
        return run
    return wrap

