TAX = 0.2


class Bill:
    def __init__(self, items, coupon=None):
        self.items, self.coupon = items, coupon

    def subtotal(self):
        return sum(i["price"] * i["qty"] for i in self.items)


def subtotal(items):
    return Bill(items).subtotal()


def tax(items):
    return round(subtotal(items) * TAX, 2)


def total(items, coupon=None):
    t = subtotal(items) + tax(items)
    return t - coupon["off"] if coupon else t
